package com.dappunq.persistence;
import com.dappunq.model.valuation.*; import jakarta.persistence.*; import java.time.*;
@Entity @Table(name="configuraciones_estrategia") public class StrategyConfigEntity { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) Long id; @ManyToOne(optional=false) @JoinColumn(name="usuario_id") UserEntity user; @Enumerated(EnumType.STRING) StrategyType estrategia; @Column(nullable=false,length=2000) String pesos; @Enumerated(EnumType.STRING) StrategyStatus estado; @Column(name="vigente_desde") Instant vigenteDesde; protected StrategyConfigEntity(){} public StrategyConfigEntity(UserEntity u,StrategyType s,String p,StrategyStatus e,Instant v){user=u;estrategia=s;pesos=p;estado=e;vigenteDesde=v;} public Long getId(){return id;} public UserEntity getUser(){return user;} public StrategyType getEstrategia(){return estrategia;} public String getPesos(){return pesos;} public StrategyStatus getEstado(){return estado;} public Instant getVigenteDesde(){return vigenteDesde;} public void setEstado(StrategyStatus e){estado=e;} }
